corrected_code:
io.on('connection', (socket) => {
  socket.on('chat:delete_message', async ({ channelId, messageId }) => {
    const msg = await db('channel_messages').where({ id: messageId, channel_id: channelId }).first();
    if (!msg || (msg.author_id !== socket.data.userId && !socket.data.isAdmin)) {
      return socket.emit('error', { message: 'Cannot delete messages authored by other users' });
    }
    await db('channel_messages').where({ id: messageId }).delete();
    io.to(`channel:${channelId}`).emit('message_deleted', { messageId });
  });
});
